'use client'; // Generated by scripts/playground.mjs from examples/components/inline-edit/0.tsx. Do not edit.

import * as React from 'react';
import { InlineEdit } from '@nexub/react';
import { PlaygroundView, type PlaygroundViewProps } from '../GeneratedPlayground';

function Base(pg: Record<string, unknown>) {
  const [name, setName] = React.useState('Q4 launch plan');
  return (
    <InlineEdit
      label="Project name"
      placeholder="Add a name"
      value={name}
      onSave={(next) => {
        if (!next.trim()) return Promise.reject(new Error('Name is required'));
        setName(next.trim());
      }} {...pg}
    />
  );
}

export default function Generated(props: PlaygroundViewProps) {
  return <PlaygroundView {...props} base={Base} />;
}
